fn make_vec() -> Vec[Int] {
  let v = Vec[Int]();
  v.push(1); v.push(2); v.push(3);
  return v;  // moves to caller — no drop here
}

fn main() -> Int {
  let data = make_vec();
  let len = data.len();
  // data dropped here — memory freed
  return len;
}
